// Compares our BPE tokenizer against ids produced by Hugging Face `tokenizers`
// (tests/data/tokenizer_cases.json, generated by tools/reference.py).
#include <cstdio>

#include "../src/json.h"
#include "../src/tokenizer.h"
#include "../src/util.h"

int main(int argc, char** argv) {
    if (argc < 3) {
        fprintf(stderr, "usage: %s <model_dir> <tokenizer_cases.json>\n", argv[0]);
        return 2;
    }
    Tokenizer tok(std::string(argv[1]) + "/tokenizer.json");
    json::Value cases = json::parse(read_file(argv[2]));
    int fail = 0;
    for (auto& c : cases.arr) {
        const std::string& text = c["text"].str;
        std::vector<int> want;
        for (auto& v : c["ids"].arr) want.push_back((int)v.as_int());
        std::vector<int> got = tok.encode(text);
        // Text that is already NFC must also survive the decode round trip.
        bool ok = got == want && (nfc_normalize(text) != text || tok.decode(got) == text);
        if (!ok) {
            fail++;
            printf("FAIL\n  want: [%zu]", want.size());
            for (int id : want) printf(" %d", id);
            printf("\n  got: [%zu]", got.size());
            for (int id : got) printf(" %d", id);
            printf("\n  text: %s\n", text.c_str());
        }
    }
    printf("tokenizer: %zu cases, %d failed\n", cases.arr.size(), fail);
    return fail ? 1 : 0;
}
